{
 "summary": "The main theorem states: for n ≥ 1, if S ⊂ ℝⁿ is compact and convex with nonempty interior, its Lebesgue barycenter is 0, and int(S) ∩ ℤⁿ = {0}, then vol(S) ≤ (n+1)ⁿ/n!. Companion theorems establish sharpness. The simplex (n+1)Δₙ − (1,…,1) has barycenter 0 and volume (n+1)ⁿ/n!, and some CenteredBody attains that volume. The statements faithfully match Theorem 1.1 and its sharpness remark. The only caveats are benign: an unneeded hypothesis n > 0, and a junk-value barycenter definition that the full-dimensionality hypothesis makes irrelevant.",
 "glossary": [
  {"decl": "Ehrhart.Space", "line": 10, "plain": "ℝⁿ as Fin n → ℝ (sup-norm topology, product Lebesgue measure)", "standard_concept": "Euclidean space ℝⁿ", "matches_standard": "yes", "note": "The topology and Lebesgue measure agree with the Euclidean ones; only the norm differs, and the norm is irrelevant here."},
  {"decl": "Ehrhart.integerPoint", "line": 12, "plain": "inclusion ℤⁿ → ℝⁿ", "standard_concept": "lattice ℤⁿ ⊂ ℝⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.standardSimplex", "line": 15, "plain": "Δₙ = {x ≥ 0, Σxᵢ ≤ 1} = conv{0,e₁,…,eₙ}", "standard_concept": "standard simplex Δₙ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.simplexDilation", "line": 18, "plain": "x ↦ (n+1)x − (1,…,1)", "standard_concept": null, "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.centeredSimplex", "line": 21, "plain": "(n+1)Δₙ − (1,…,1)", "standard_concept": "the extremal simplex of the paper", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.normalizedVolume", "line": 24, "plain": "Lebesgue volume of K as a real number (0 if infinite)", "standard_concept": "vol(K)", "matches_standard": "yes", "note": "Despite the name, this is ordinary volume, not n!·vol; that matches the paper's vol. It is finite for compact K."},
  {"decl": "Ehrhart.barycenter", "line": 27, "plain": "vol(K)⁻¹ ∫_K x dx", "standard_concept": "barycenter (centroid)", "matches_standard": "yes", "note": "The value is junk (0) if vol(K)=0 or the integral fails; both are excluded for compact sets with nonempty interior."},
  {"decl": "Ehrhart.interiorLatticePoints", "line": 30, "plain": "int(K) ∩ ℤⁿ", "standard_concept": "interior lattice points", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.CenteredBody", "line": 33, "plain": "convex compact full-dimensional K with barycenter 0 and int(K)∩ℤⁿ={0}", "standard_concept": "Theorem 1.1 hypothesis class", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.sharpConstant", "line": 41, "plain": "(n+1)ⁿ/n!", "standard_concept": "Ehrhart bound", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "line": 48, "plain": "For all n, the barycenter of (n+1)Δₙ − (1,…,1) is 0."},
  {"theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "line": 52, "plain": "For n > 0, vol((n+1)Δₙ − (1,…,1)) = (n+1)ⁿ/n!."},
  {"theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 56, "plain": "For n > 0 there is a convex compact full-dimensional K ⊂ ℝⁿ with barycenter 0, int(K)∩ℤⁿ={0}, and vol(K) = (n+1)ⁿ/n!."},
  {"theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "line": 65, "plain": "For n > 0 and S ⊂ ℝⁿ convex, compact, with nonempty interior, barycenter 0, and int(S)∩ℤⁿ={0}: vol(S) ≤ (n+1)ⁿ/n!."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "If K ⊂ ℝⁿ is a full-dimensional compact convex body with barycenter 0 and int(K)∩ℤⁿ={0}, then vol(K) ≤ (n+1)ⁿ/n!."},
  {"ref": "Sharpness remark after Theorem 1.1", "plain": "The simplex (n+1)Δₙ − (1,…,1) has barycenter 0, no other interior lattice point, and volume (n+1)ⁿ/n!."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "relation": "equivalent", "why": "Hypotheses and conclusion match. The extra n>0 only excludes the trivial n=0 case."},
  {"paper_ref": "Sharpness remark after Theorem 1.1", "lean_theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "relation": "equivalent", "why": "The barycenter and volume of the specific simplex are proved separately. Existence of an extremal CenteredBody covers the unique-interior-lattice-point condition."}
 ],
 "flags": [
  {"id": "F1", "category": "assumption", "severity": "low", "decl": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "line": 66, "paper_ref": "Theorem 1.1", "explanation": "The hypothesis 0 < n is extra. At n=0, Space 0 is a point of volume 1 and the bound is 1, so the excluded case is trivial.", "polarity": "lean weaker", "probe_idea": "Prove the statement for n = 0 directly: volume (univ : Set (Fin 0 → ℝ)) = 1."},
  {"id": "F2", "category": "junk-value", "severity": "low", "decl": "Ehrhart.barycenter", "line": 27, "paper_ref": "Theorem 1.1", "explanation": "The barycenter is 0 by junk value if vol(K)=0. Nonempty interior plus compactness forces 0 < vol < ∞, so the hypothesis barycenter S = 0 is genuine.", "polarity": "n/a", "probe_idea": "Lemma: IsCompact S → (interior S).Nonempty → 0 < normalizedVolume S."},
  {"id": "F3", "category": "coverage", "severity": "low", "decl": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 56, "paper_ref": "Sharpness remark after Theorem 1.1", "explanation": "There is no separate theorem that the centered simplex itself has int ∩ ℤⁿ = {0}. Sharpness is expressed as existence of some CenteredBody attaining the bound, which suffices for sharpness. Equality cases are not formalized, but the paper explicitly does not claim them.", "polarity": "n/a", "probe_idea": "interiorLatticePoints (centeredSimplex n) = {0}."}
 ],
